u0440 \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 Llama-2: \u043e\u0434\u043d\u0430 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430, \u043e\u0434\u0438\u043d \u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440, \u043e\u0434\u0438\u043d \u043a\u043e\u0440\u043f\u0443\u0441 \u043f\u0440\u0435-training. \u0423\u0440\u043e\u0432\u043d\u0438 \u0432\u044b\u0431\u0440\u0430\u043d\u044b \u043f\u043e\u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u0440\u044f\u043c\u043e \u0437\u0430\u0434\u0430\u043d \u043e \u043f\u0430\u0440\u0435 13B\u219470B; 7B \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043c\u043b\u0430\u0434\u0448\u0430\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u0430\u044f \u0442\u043e\u0447\u043a\u0430 \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 \u0444\u043e\u0440\u043c\u044b \u043a\u0440\u0438\u0432\u043e\u0439 \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u2192 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e\u00bb (\u043d\u0430\u0441\u044b\u0449\u0435\u043d\u0438\u0435 vs \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u044b\u0439 \u0440\u043e\u0441\u0442).\n- **\u041e\u0441\u044c B. \u041d\u0435\u043f\u043e\u043b\u043d\u043e\u0442\u0430 \u043f\u0440\u0435-training (1T vs 2T \u0442\u043e\u043a\u0435\u043d\u043e\u0432)** \u2014 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u00ab\u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u0440\u0435-training\u00bb \u043a\u0430\u043a \u00ab\u043c\u0435\u043d\u044c\u0448\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432 \u0442\u043e\u043c \u0436\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u0435\u00bb: \u0434\u043b\u044f 7B/13B \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0442 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0435 \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u044b \u043d\u0430 1T \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (\u043e\u043f\u0438\u0441\u0430\u043d\u044b/\u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0432 \u0442\u0435\u0445\u043e\u0442\u0447\u0451\u0442\u0435 Llama-2) \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0438\u0441\u0430\u043d\u0438\u044f 2T. \u042d\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u00ab\u043d\u0435\u043f\u043e\u043b\u043d\u043e\u0442\u0443\u00bb \u0441\u0440\u0430\u0432\u043d\u0438\u043c\u043e\u0439 \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u043e\u0440\u043f\u0443\u0441\u0430 \u0438 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0434\u0430\u043d\u043d\u044b\u0445). \u0420\u0435\u0436\u0438\u043c \u00ab\u043a\u0430\u0442\u0430\u0441\u0442\u0440\u043e\u0444\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u0434\u043e\u043f\u0440\u0435\u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e\u00bb (\u043d\u0438\u0436\u0435 Chinchilla-\u043e\u043f\u0442\u0438\u043c\u0443\u043c\u0430) \u0432\u044b\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u0432 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u043b\u0435\u0447\u043e \u0447\u0435\u0440\u0435\u0437 \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u0437\u0430\u043a\u043e\u043d (\u043f. 5).\n- **\u041e\u0441\u044c C. \u0412\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435 (base / SFT / chat)** \u2014 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u00ab\u0441\u043b\u0430\u0431\u043e\u0433\u043e/\u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0433\u043e \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f\u00bb: base (\u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0435-training), SFT (\u0442\u043e\u043b\u044c\u043a\u043e instruction tuning), chat (RLHF + safety tuning). \u0412\u0441\u0435 \u0442\u0440\u0438 \u0441\u0442\u0430\u0434\u0438\u0438 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u044b \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0440\u0430\u0437\u043c\u0435\u0440\u0430; \u0440\u0435\u0446\u0435\u043f\u0442 \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0430\u0434\u0438\u0438 \u0432 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0435 Llama-2 \u0435\u0434\u0438\u043d\u044b\u0439 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432, \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u0443\u0440\u043e\u0432\u043d\u0438 \u043e\u0441\u0438 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u044b\u043c\u0438.\n\n**\u0427\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043a\u0430\u0436\u0434\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442:** (\u0441\u043c. \u043f. 2) \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 1 \u2014 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u0430\u044f \u043a\u0440\u0438\u0432\u0430\u044f \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c \u043f\u0440\u0435-training\u00bb; \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 2 \u2014 \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u043d\u0435\u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043f\u0440\u0435-training \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435 (\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b \u0442\u043e\u043a\u0435\u043d-\u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0441 \u0440\u0430\u0437\u043c\u0435\u0440-\u044d\u0444\u0444\u0435\u043a\u0442\u043e\u043c); \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 3 \u2014 \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 alignment \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435/\u043e\u0431\u044a\u0451\u043c\u0435; \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u044b 4\u20135 \u2014 \u043f\u0440\u044f\u043c\u043e\u0435 \u0442\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0442\u0435\u0437\u0438\u0441\u0430 \u043e \u00ab\u0441\u0432\u0435\u0434\u0435\u043d\u0438\u0438 \u043d\u0430 \u043d\u0435\u0442\u00bb \u0432\u044b\u0438\u0433\u0440\u044b\u0448\u0430 \u043e\u0442 \u0440\u0430\u0437\u043c\u0435\u0440\u0430 \u0441\u043b\u0430\u0431\u044b\u043c \u043f\u0440\u0435-training \u0438/\u0438\u043b\u0438 \u0441\u043b\u0430\u0431\u044b\u043c \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435\u043c.\n\n## 2) \u041f\u043e\u043b\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439 \u0438 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0445 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432\n\n**\u041c\u0430\u0442\u0440\u0438\u0446\u0430 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439 (\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0435 \u043a\u043b\u0435\u0442\u043a\u0438):** \u0440\u0430\u0437\u043c\u0435\u0440\u044b 7B/13B/70B \u00d7 \u0442\u043e\u043a\u0435\u043d\u044b {1T, 2T} (1T \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f 7B/13B; 70B \u0442\u043e\u043b\u044c\u043a\u043e 2T) \u00d7 \u0441\u0442\u0430\u0434\u0438\u044f {base, SFT, chat} (\u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0439 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0446\u0438\u0438 \u0440\u0430\u0437\u043c\u0435\u0440\u00d7\u0442\u043e\u043a\u0435\u043d\u044b \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0432\u0441\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0435 \u0441\u0442\u0430\u0434\u0438\u0438).\n\n**\u041a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u044b:**\n1. **\u041a\u0440\u0438\u0432\u0430\u044f \u0440\u0430\u0437\u043c\u0435\u0440\u0430 (\u044d\u0442\u0430\u043b\u043e\u043d):** 7B-base(2T), 13B-base(2T), 70B-base(2T). \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435: \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u044b\u0439 \u0440\u043e\u0441\u0442 \u043f\u043e \u0432\u0441\u0435\u043c \u0451\u043c\u043a\u043e\u0441\u0442\u043d\u044b\u043c \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u043c, \u0441 \u0431\u043e\u043b\u0435\u0435 \u0441\u0438\u043b\u044c\u043d\u044b\u043c \u0440\u043e\u0441\u0442\u043e\u043c \u043d\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0438/\u043a\u043e\u0434\u0435 \u0438 \u0431\u043e\u043b\u0435\u0435 \u0441\u0436\u0430\u0442\u044b\u043c/\u043d\u0430\u0441\u044b\u0449\u0430\u044e\u0449\u0438\u043c\u0441\u044f \u0440\u043e\u0441\u0442\u043e\u043c \u043d\u0430 \u043d\u0430\u0441\u044b\u0449\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u0437\u0430\u0434\u0430\u0447\u0430\u0445 \u0437\u043d\u0430\u043d\u0438\u0439/\u043a\u043e\u043c\u043c\u043e\u043d-\u0441\u0435\u043d\u0441\u0430.\n2. **\u042d\u0444\u0444\u0435\u043a\u0442 \u043d\u0435\u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043f\u0440\u0435-training \u043f\u0440\u0438 \u0444\u0438\u043a\u0441. \u0440\u0430\u0437\u043c\u0435\u0440\u0435:** 7B-base(1T) vs 7B-base(2T); 13B-base(1T) vs 13B-base(2T). \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435: 2T \u227b 1T \u043f\u043e\u0447\u0442\u0438 \u0432\u0435\u0437\u0434\u0435; \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u0442\u0435\u0441\u0442 \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b \u044d\u0442\u043e\u0433\u043e \u043f\u0440\u0438\u0440\u043e\u0441\u0442\u0430 \u0441 \u043f\u0440\u0438\u0440\u043e\u0441\u0442\u043e\u043c 13B(2T)\u219270B(2T) \u043f\u043e \u0442\u0435\u043c \u0436\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u043c (\u0442\u043e\u043a\u0435\u043d-\u044d\u0444\u0444\u0435\u043a\u0442 vs \u0440\u0430\u0437\u043c\u0435\u0440-\u044d\u0444\u0444\u0435\u043a\u0442).\n3. **\u042d\u0444\u0444\u0435\u043a\u0442 alignment \u043f\u0440\u0438 \u0444\u0438\u043a\u0441. \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u0438 \u0444\u0438\u043a\u0441. \u043e\u0431\u044a\u0451\u043c\u0435:** 13B \u0438 70B \u0432 {base, SFT, chat} \u043f\u0440\u0438 2T. \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435: \u043d\u0430 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0445/\u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u0445 chat \u227b SFT \u226b base; \u043d\u0430 \u0451\u043c\u043a\u043e\u0441\u0442\u043d\u044b\u0445 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u0445 \u0441\u0442\u0430\u0434\u0438\u0438 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u044b (\u043c\u0430\u043b\u044b\u0435 \u0434\u0435\u043b\u044c\u0442\u044b), \u0447\u0442\u043e \u0432 \u0438\u0434\u0435\u0430\u043b\u0435 \u0434\u0435\u043b\u0430\u0435\u0442 alignment \u00ab\u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u043e\u0439\u00bb \u043c\u0430\u043d\u0438\u043f\u0443\u043b\u044f\u0446\u0438\u0435\u0439 \u0438 \u0443\u043f\u0440\u043e\u0449\u0430\u0435\u0442 \u0430\u0442\u0440\u0438\u0431\u0443\u0446\u0438\u044e.\n4. **\u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 C1 \u00ab\u0445\u043e\u0440\u043e\u0448\u043e \u0432\u044b\u0440\u0430\u0432\u043d\u0435\u043d\u043d\u044b\u0439 13B vs \u0441\u043b\u0430\u0431\u043e \u0432\u044b\u0440\u0430\u0432\u043d\u0435\u043d\u043d\u044b\u0439 70B\u00bb:** 13B-chat(2T) vs 70B-base(2T) \u0438 vs 70B-SFT(2T). \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435: \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043c\u0435\u043d\u044c\u0448\u0438\u0439 \u0440\u0430\u0437\u043c\u0435\u0440, 13B-chat \u2265 70B-base/SFT \u043f\u043e helpfulness+harmlessness (refusal rate, safety categories, MT-Bench), \u043f\u0440\u0438 \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0438 70B \u043f\u043e \u0441\u044b\u0440\u043e\u0439 \u0451\u043c\u043a\u043e\u0441\u0442\u0438. \u0415\u0441\u043b\u0438 \u0442\u0430\u043a \u2014 \u0438\u043c\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u21d2 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e-\u043f\u043e\u0441\u043b\u0435-alignment\u00bb \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0433\u043d\u0443\u0442\u0430.\n5. **\u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 C2 \u00ab\u043d\u0435\u0434\u043e\u043f\u0440\u0435\u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043c\u0435\u043d\u044c\u0448\u0438\u0439 vs \u043f\u043e\u043b\u043d\u044b\u0439 \u0431\u043e\u043b\u044c\u0448\u0438\u0439 (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c)\u00bb:** 13B-base(1T) vs 70B-base(2T), \u0441 \u043f\u0430\u0440\u043e\u0439 13B-base(2T) vs 70B-base(2T) \u0434\u043b\u044f \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0447\u0438\u0441\u0442\u043e\u0433\u043e \u0440\u0430\u0437\u043c\u0435\u0440\u0430 \u0438 \u043f\u0430\u0440\u043e\u0439 13B-base(1T) vs 13B-base(2T) \u0434\u043b\u044f \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u043e\u0446\u0435\u043d\u043a\u0438 \u0442\u043e\u043a\u0435\u043d-\u044d\u0444\u0444\u0435\u043a\u0442\u0430. \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435: \u043f\u043e \u0451\u043c\u043a\u043e\u0441\u0442\u0438 70B \u043f\u043e\u0431\u0435\u0436\u0434\u0430\u0435\u0442 (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f); \u0434\u0438\u0437\u0430\u0439\u043d \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442, \u0447\u0442\u043e \u00ab\u043d\u0435\u043f\u043e\u043b\u043d\u043e\u0442\u0430 \u043f\u0440\u0435-training\u00bb \u0432 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u043c \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 \u043d\u0435 \u0438\u043d\u0432\u0435\u0440\u0442\u0438\u0440\u0443\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043f\u043e \u0441\u044b\u0440\u043e\u0439 \u0451\u043c\u043a\u043e\u0441\u0442\u0438, \u0430 \u00ab\u0441\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043d\u0430 \u043d\u0435\u0442\u00bb \u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u043c \u043f\u0440\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u043e\u043c \u043f\u043b\u0435\u0447\u0435 \u0438 \u0432 \u044d\u043a\u0441\u0442\u0440\u0430\u043f\u043e\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435 (\u043f. 5).\n6. **\u041a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 C3 \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u00d7 \u043f\u0440\u0435-training (\u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0435)\u00bb:** \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u043b\u0435\u0447\u043e \u2014 \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u0438\u0435 \u0437\u043e\u043d\u044b \u043a\u0440\u043e\u0441\u0441\u043e\u0432\u0435\u0440\u0430, \u0433\u0434\u0435 13B \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u227d 70B \u043f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c; \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043f\u0443\u0442\u044c \u043f\u043e\u043a\u0440\u044b\u0442\u044c \u043d\u0435\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0439 70B@1T (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u0437\u0430\u043a\u043e\u043d\u0430).\n7. **\u041a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 C4 \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u00d7 alignment (\u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435)\u00bb:** \u0440\u0430\u0441\u0442\u0451\u0442 \u043b\u0438 \u0440\u0430\u0437\u0440\u044b\u0432 base\u2194chat \u043f\u043e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0441 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c (\u0431\u043e\u043b\u044c\u0448\u0438\u0435 base-\u043c\u043e\u0434\u0435\u043b\u0438 \u0441\u043a\u043b\u043e\u043d\u043d\u0435\u0435 \u043a \u0432\u0440\u0435\u0434\u043d\u043e\u043c\u0443 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u044e \u043f\u0440\u0438 \u0441\u043b\u0430\u0431\u043e\u043c alignment, \u043a\u0430\u043a \u043e\u0442\u043c\u0435\u0447\u0435\u043d\u043e \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 Llama-2) \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u00ab\u0446\u0435\u043d\u0430 \u043d\u0435\u0445\u0432\u0430\u0442\u043a\u0438 alignment\u00bb \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c.\n\n**\u041e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0435 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u044b \u043f\u043e \u0442\u0438\u043f\u0430\u043c \u043c\u0435\u0442\u0440\u0438\u043a (\u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0441\u0430\u043d\u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438 \u0434\u0438\u0437\u0430\u0439\u043d\u0430):**\n- *\u041d\u0430\u0441\u044b\u0449\u0430\u044e\u0449\u0438\u0435\u0441\u044f (\u0437\u043d\u0430\u043d\u0438\u044f/\u043a\u043e\u043c\u043c\u043e\u043d-\u0441\u0435\u043d\u0441: MMLU, HellaSwag, WinoGrande, PIQA, ARC-c):* \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u044b\u0439, \u043d\u043e \u0441\u0436\u0438\u043c\u0430\u044e\u0449\u0438\u0439\u0441\u044f \u043f\u0440\u0438\u0440\u043e\u0441\u0442 \u0441 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c; \u0431\u043e\u043b\u0435\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u044b \u043a \u043e\u0431\u044a\u0451\u043c\u0443 \u0442\u043e\u043a\u0435\u043d\u043e\u0432, \u0447\u0435\u043c \u043a \u0440\u0430\u0437\u043c\u0435\u0440\u0443 \u0432 \u043a\u0440\u0443\u043f\u043d\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435 \u2192 \u0433\u043b\u0430\u0432\u043d\u044b\u0435 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u044b \u043d\u0430 \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u0435 \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u21d2 \u0432\u0441\u0435\u0433\u0434\u0430 \u043b\u0443\u0447\u0448\u0435\u00bb (\u0437\u043e\u043d\u0430 \u0442\u043e\u043a\u0435\u043d-\u044d\u0444\u0444\u0435\u043a\u0442 \u2265 \u0440\u0430\u0437\u043c\u0435\u0440-\u044d\u0444\u0444\u0435\u043a\u0442).\n- *\u0401\u043c\u043a\u043e\u0441\u0442\u043d\u043e-\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 (\u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435/\u043a\u043e\u0434: GSM8K, MATH, BBH, HumanEval):* \u0441\u0438\u043b\u044c\u043d\u044b\u0439 \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u044b\u0439 \u0440\u043e\u0441\u0442 \u0441 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c; \u0437\u0434\u0435\u0441\u044c \u0440\u0430\u0437\u043c\u0435\u0440, \u043a\u0430\u043a \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f, \u0434\u0435\u0440\u0436\u0438\u0442 \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u2192 \u044d\u0442\u043e \u00ab\u0433\u0434\u0435 \u0440\u0430\u0437\u043c\u0435\u0440 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442\u00bb (\u0441\u0430\u043d\u0438\u0442\u0438-\u0447\u0435\u043a\u0430).\n- *\u041f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0435/\u043f\u043e\u0441\u043b\u0435-alignment (refusal rate, \u0432\u0440\u0435\u0434\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u0439, safety categories, \u0442\u043e\u043a\u0441\u0438\u0447\u043d\u043e\u0441\u0442\u044c, MT-Bench/AlpacaEval):* \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u0435\u0442 \u043e\u0441\u044c alignment, \u0430 \u043d\u0435 \u0440\u0430\u0437\u043c\u0435\u0440; \u043f\u0440\u0438 \u0441\u043b\u0430\u0431\u043e\u043c alignment \u0431\u043e\u043b\u044c\u0448\u0438\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u043c\u043e\u0436\u0435\u0442 \u043a\u043e\u0440\u0440\u0435\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441 \u0431\u043e\u043b\u044c\u0448\u0435\u0439 \u043f\u043e\u0434\u0430\u0442\u043b\u0438\u0432\u043e\u0441\u0442\u044c\u044e \u0432\u0440\u0435\u0434\u043d\u044b\u043c \u043f\u0440\u043e\u043c\u043f\u0442\u0430\u043c \u2192 \u0441\u0430\u043c\u043e\u0435 \u0447\u0438\u0441\u0442\u043e\u0435 \u043c\u0435\u0441\u0442\u043e, \u0433\u0434\u0435 \u00ab\u0431\u043e\u043b\u044c\u0448\u0435 \u21d2 \u043b\u0443\u0447\u0448\u0435\u00bb \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f.\n\n## 3) \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\n\n- **\u0415\u0434\u0438\u043d\u044b\u0439 eval-harness \u0438 \u0448\u0430\u0431\u043b\u043e\u043d\u044b:** \u043e\u0434\u0438\u043d \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u043e\u0446\u0435\u043d\u043a\u0438; \u0432\u043d\u0443\u0442\u0440\u0438 \u0437\u0430\u0434\u0430\u0447\u0438 \u2014 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 few-shot \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438, \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u0448\u0430\u0431\u043b\u043e\u043d\u044b \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432, greedy-\u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 (temperature=0, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 max_new_tokens), \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 eval-\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439/\u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432.\n- **\u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b base-\u0443\u0440\u043e\u0432\u043d\u044f (\u043c\u0435\u0442\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435, \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e):** base-\u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f\u043c, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043e\u043d\u0430 \u041d\u0415 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u0435\u043c \u0436\u0435 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u043e\u043c, \u0447\u0442\u043e SFT/chat, \u043d\u0430 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u0445. \u0414\u0432\u0430 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u0445 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0442\u0440\u0435\u043a\u0430: (a) \u0447\u0430\u0442/SFT-\u0442\u0440\u0435\u043a \u2014 \u0448\u0430\u0431\u043b\u043e\u043d Llama-2 chat + system prompt; (b) base-\u0442\u0440\u0435\u043a \u2014 continuation/few-shot \u00ab\u0441\u044b\u0440\u043e\u0439\u00bb \u0448\u0430\u0431\u043b\u043e\u043d (\u043f\u0440\u0438\u043c\u0435\u0440\u044b-\u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f, \u0431\u0435\u0437 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u043e\u0433\u043e \u0440\u0430\u043f\u043f\u0435\u0440\u0430 \u0438 system prompt) \u043f\u043e \u043e\u0431\u0440\u0430\u0437\u0446\u0443 \u043e\u0442\u0447\u0451\u0442\u0430 Llama-2. \u041d\u0430 base-\u0442\u0440\u0435\u043a\u0435 refusal rate \u0438 helpfulness \u041d\u0415 \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u00ab\u043e\u0442\u043a\u0430\u0437/\u043f\u043e\u043b\u0435\u0437\u043d\u043e\u0441\u0442\u044c \u0432 \u0441\u043c\u044b\u0441\u043b\u0435 \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f\u043c\u00bb (\u043d\u0435\u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c\u044b \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e); \u0432\u043c\u0435\u0441\u0442\u043e \u043d\u0438\u0445 \u2014 \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u00ab\u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u044f\u00bb (\u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0447\u0430\u0441\u0442\u043e \u043c\u043e\u0434\u0435\u043b\u044c \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0432\u0440\u0435\u0434\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442 \u043f\u0440\u0438 \u0432\u0440\u0435\u0434\u043d\u043e\u043c \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u0435) \u0438 \u00ab\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u043d\u0435\u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0448\u0430\u0431\u043b\u043e\u043d\u0430\u043c\u00bb (accuracy few-shot). \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u00abbase vs chat \u043f\u043e refusal rate\u00bb \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u043c \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u043c \u0438 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u0440\u0435\u0448\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e; \u044d\u0444\u0444\u0435\u043a\u0442 alignment \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u043e \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u043c \u043f\u0430\u0440\u0430\u043c (SFT\u2194chat \u043d\u0430 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u0445; base \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u043c \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u043d\u043e\u043c \u0442\u0440\u0435\u043a\u0435) \u0441\u043e \u0441\u0442\u0440\u043e\u0433\u043e\u0439 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u043e\u0439 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438.\n- **\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430:** \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0435 \u0441\u0438\u0434\u044b (N\u22655) \u0434\u043b\u044f \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u044d\u0432\u0430\u043b\u043e\u0432; bootstrap-\u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b; \u043f\u0430\u0440\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (\u043e\u0431\u0449\u0438\u0435 eval-\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b \u0447\u0435\u0440\u0435\u0437 \u043c\u043e\u0434\u0435\u043b\u0438 \u0441\u043d\u0438\u0436\u0430\u044e\u0442 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u044e). \u0417\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0439 \u043f\u043e\u0440\u043e\u0433 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u22652\u20133 \u043f.\u043f. \u043d\u0430 \u0451\u043c\u043a\u043e\u0441\u0442\u043d\u044b\u0445 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u0445; \u0434\u043b\u044f \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0445 \u2014 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0439 \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0439 \u043f\u043e\u0440\u043e\u0433 \u043f\u043e rates).\n- **\u0415\u0434\u0438\u043d\u044b\u0439 \u0440\u0435\u0446\u0435\u043f\u0442 alignment \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0430\u0434\u0438\u0438:** \u0432 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0435 Llama-2 \u0441\u0442\u0430\u0434\u0438\u044f SFT/chat \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043f\u043e \u043e\u0434\u043d\u043e\u043c\u0443 \u0440\u0435\u0446\u0435\u043f\u0442\u0443 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432 (\u0442\u0435 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0438 \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0442\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435) \u2014 \u044d\u0442\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u0441\u0442\u0438 \u0443\u0440\u043e\u0432\u043d\u0435\u0439 \u043e\u0441\u0438 C; \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435, \u0430 \u043d\u0435 \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435.\n- **\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u043e\u0432:** \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u043a\u043e\u0440\u043f\u0443\u0441 \u0438 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0434\u0430\u043d\u043d\u044b\u0445 \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u0443\u0440\u043e\u0432\u043d\u044f \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (1T/2T \u2014 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430); \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440; throughput/\u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e\u043c; \u043d\u0438\u043a\u0430\u043a\u043e\u0433\u043e \u0434\u043e\u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f/\u043f\u043e\u0441\u0442\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043c\u0435\u0436\u0434\u0443 \u043a\u043b\u0435\u0442\u043a\u0430\u043c\u0438 \u043c\u0430\u0442\u0440\u0438\u0446\u044b.\n\n## 4) \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0438 \u0440\u0435\u0448\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e\n\n- **\u041f\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f** \u043d\u0430\u0431\u043e\u0440\u0430 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u043e\u0432, \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u043e\u0432 \u0438 \u043f\u043e\u0440\u043e\u0433\u043e\u0432 \u0414\u041e \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u043f\u043e\u0441\u0442-\u0445\u043e\u043a \u043e\u0442\u0431\u043e\u0440\u0430).\n- **\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u0440\u0435\u0448\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e (\u0444\u0430\u043b\u044c\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0435):** \u0435\u0441\u043b\u0438 \u043d\u0430\u0439\u0434\u0451\u0442\u0441\u044f \u0445\u043e\u0442\u044f \u0431\u044b \u043e\u0434\u043d\u043e \u043f\u0440\u0435\u0434\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0435, \u0433\u0434\u0435 \u0431\u043e\u043b\u044c\u0448\u0438\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u043f\u0440\u0438 \u043d\u0435\u043f\u043e\u043b\u043d\u043e\u043c \u043f\u0440\u0435-training (\u043e\u0441\u044c B) \u0438/\u0438\u043b\u0438 \u0441\u043b\u0430\u0431\u043e\u043c \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0438 (\u043e\u0441\u044c C) \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e (bootstrap-\u0414\u0418 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 0) \u0418 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e (\u2265 \u0437\u0430\u0434\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u043e\u0433\u0430) \u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442 \u043c\u0435\u043d\u044c\u0448\u0435\u043c\u0443 \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u043c\u043e\u043c\u0443 \u2014 \u0438\u043c\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u21d2 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u044f \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430\u00bb \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0433\u043d\u0443\u0442\u043e\u0439. \u0412 \u043e\u0442\u0447\u0451\u0442\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f, \u043a\u0430\u043a\u043e\u0435 \u0438\u043c\u0435\u043d\u043d\u043e(\u044b\u0435) \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0435(\u044f) \u0438 \u043f\u0440\u0438 \u043a\u0430\u043a\u0438\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u043e\u0441\u0438 \u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u0435.\n- **\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u043e\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e (\u0441\u0438\u043b\u0430 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432):** \u043f\u043e\u0434\u0441\u0447\u0451\u0442 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0439, \u0433\u0434\u0435 \u0440\u0430\u0437\u043c\u0435\u0440 \u0434\u0435\u0440\u0436\u0438\u0442 \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e vs \u0433\u0434\u0435 \u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442. \u0415\u0441\u043b\u0438 \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u043e\u043c \u043f\u043b\u0435\u0447\u0435 \u043f\u0440\u0438 \u0441\u043b\u0430\u0431\u043e\u043c alignment \u0438/\u0438\u043b\u0438 \u0432 \u044d\u043a\u0441\u0442\u0440\u0430\u043f\u043e\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u043e\u0439 \u0437\u043e\u043d\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u2014 \u0432\u044b\u0432\u043e\u0434 \u0443\u0442\u043e\u0447\u043d\u044f\u0435\u0442\u0441\u044f: \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0441\u044b\u0440\u0443\u044e \u0451\u043c\u043a\u043e\u0441\u0442\u044c \u043d\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447\u0430\u0445, \u043d\u043e \u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e-\u043f\u043e\u0441\u043b\u0435-alignment \u0438 \u043d\u0435 \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0438\u0440\u0443\u0435\u0442 \u043d\u0435\u0445\u0432\u0430\u0442\u043a\u0443 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u043d\u0430 \u043d\u0430\u0441\u044b\u0449\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u0445\u00bb.\n- **\u0415\u0441\u043b\u0438 \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u0435 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e:** \u0432\u044b\u0432\u043e\u0434 \u2014 \u00ab\u043d\u0435\u0442 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432 \u043e\u0442\u0440\u0438\u0446\u0430\u043d\u0438\u044f \u0432 \u043f\u043e\u043a\u0440\u044b\u0442\u043e\u043c \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u0435 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439\u00bb, \u0431\u0435\u0437 \u043f\u0440\u0435\u0442\u0435\u043d\u0437\u0438\u0438 \u043d\u0430 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u0443\u044e \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u044e (\u0434\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u00ab\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u00bb \u0432 \u043f\u0440\u0438\u043d\u0446\u0438\u043f\u0435 \u043d\u0435\u043b\u044c\u0437\u044f; \u0432\u044b\u0432\u043e\u0434 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d \u043c\u0430\u0442\u0440\u0438\u0446\u0435\u0439 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439 \u0438 \u043d\u0430\u0431\u043e\u0440\u043e\u043c \u0437\u0430\u0434\u0430\u0447).\n- **\u0410\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u043b\u0435\u0447\u043e (\u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433):** \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 Chinchilla-\u0441\u0442\u0438\u043b\u044c \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u043f\u043e\u0442\u0435\u0440\u044c L(N,D) \u043d\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0442\u043e\u0447\u043a\u0430\u0445 (7B/13B \u043f\u0440\u0438 1T \u0438 2T, 70B \u043f\u0440\u0438 2T); \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u0438\u0435 \u043d\u0435\u0434\u043e\u0441\u0442\u0438\u0436\u0438\u043c\u044b\u0445 \u043a\u043b\u0435\u0442\u043e\u043a (70B@1T, 70B@0.5T, 13B@0.5T) \u0438 \u0437\u043e\u043d\u044b \u043a\u0440\u043e\u0441\u0441\u043e\u0432\u0435\u0440\u0430, \u0433\u0434\u0435 13B \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u0430\u0445 \u227d 70B \u043f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0445; \u0441\u0430\u043d\u0438\u0442\u0438-\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u2014 \u043c\u043e\u0434\u0435\u043b\u044c \u0434\u043e\u043b\u0436\u043d\u0430 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u044c \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0435 \u0434\u0435\u043b\u044c\u0442\u044b 1T\u21922T \u0434\u043b\u044f 7B/13B \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u0434\u043e\u043f\u0443\u0441\u043a\u0430, \u0438\u043d\u0430\u0447\u0435 \u044d\u043a\u0441\u0442\u0440\u0430\u043f\u043e\u043b\u044f\u0446\u0438\u044f \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043d\u0438\u0437\u043a\u043e\u0434\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0439.\n\n## 5) \u0412\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u044c \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f (\u0432\u043d\u0443\u0442\u0440\u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430 \u2014 \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f, \u0430 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0435 \u0444\u0430\u043a\u0442\u044b)\n\n- \u041e\u043f\u043e\u0440\u0430 \u043d\u0430 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u0442\u0435\u0445\u043e\u0442\u0447\u0451\u0442 Llama-2 (Touvron et al., 2023) \u0438 \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u0437\u0430\u043a\u043e\u043d Chinchilla (Hoffmann et al., 2022) \u043a\u0430\u043a \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438; \u043b\u044e\u0431\u044b\u0435 \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0438\u0437 \u043d\u0438\u0445 \u0446\u0438\u0442\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435, \u0430 \u043d\u0435 \u043a\u0430\u043a \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0430\u0448\u0435\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430. [\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435]\n- \u00ab\u041d\u0435\u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0440\u0435-training\u00bb \u2014 \u043f\u0440\u043e\u043a\u0441\u0438 \u00ab\u043c\u0435\u043d\u044c\u0448\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432\u00bb (1T vs 2T); \u043d\u0435 \u00ab\u043c\u0435\u043d\u0435\u0435 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u0440\u043f\u0443\u0441\u00bb. [\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435]\n- 1T-\u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u044b 7B/13B: \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f; \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c \u0434\u043b\u044f \u0441\u043a\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u044f \u2014 \u043f\u043e\u0434\u043b\u0435\u0436\u0438\u0442 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438. \u0415\u0441\u043b\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b: fallback \u2014 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 eval-\u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0434\u043b\u044f \u044d\u0442\u0438\u0445 \u043a\u043b\u0435\u0442\u043e\u043a \u043b\u0438\u0431\u043e \u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u043a\u043b\u0435\u0442\u043a\u0443 \u0438 \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u0435\u0439 \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u0437\u0430\u043a\u043e\u043d\u0430 (\u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435). [\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c]\n- 70B@1T \u043d\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 \u2192 \u0440\u0435\u0436\u0438\u043c \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e; \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u044d\u043a\u0441\u0442\u0440\u0430\u043f\u043e\u043b\u044f\u0446\u0438\u0435\u0439 \u0438/\u0438\u043b\u0438 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u043d\u044b\u043c \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e\u043c (Pythia-\u0441\u0442\u0438\u043b\u044c, \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u044b \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f) \u0441 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u043e\u0441\u0442\u0438. [\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435/\u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c]\n- \u041d\u0430\u0431\u043b\u044e\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440: \u0431\u0435\u0437 \u0440\u0435\u0442\u0440\u0435\u0439\u043d\u0430 70B \u043f\u043e\u043b\u043d\u043e\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u043d\u043e\u0435 \u043e\u0442\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0440\u0430\u0437\u043c\u0435\u0440\u0430 \u043e\u0442 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e; \u0432\u044b\u0432\u043e\u0434 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d \u043f\u043e\u043a\u0440\u044b\u0442\u044b\u043c \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u043e\u043c \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439 \u0438 \u043d\u0430\u0431\u043e\u0440\u043e\u043c \u0437\u0430\u0434\u0430\u0447; \u0432\u044b\u0438\u0433\u0440\u044b\u0448 \u0440\u0430\u0437\u043c\u0435\u0440\u0430 \u043d\u0435\u043e\u0434\u043d\u043e\u0440\u043e\u0434\u0435\u043d \u043f\u043e \u0442\u0438\u043f\u0430\u043c \u0437\u0430\u0434\u0430\u0447. [\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c]\n- \u00ab\u041a\u0430\u0447\u0435\u0441\u0442\u0432\u043e\u00bb \u043c\u043d\u043e\u0433\u043e\u043c\u0435\u0440\u043d\u043e: \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0434\u0432\u0435 \u0433\u0440\u0443\u043f\u043f\u044b \u043c\u0435\u0442\u0440\u0438\u043a (\u0451\u043c\u043a\u043e\u0441\u0442\u043d\u044b\u0435 \u0438 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0435); \u043e\u0431\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u044d\u0442\u0438\u0445 \u043c\u0435\u0442\u0440\u0438\u043a. [\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435]\n\n## 6) \u0421\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u0441 \u0431\u0440\u0438\u0444\u043e\u043c (\u043a\u0430\u0440\u0442\u0430 \u00ab\u0432\u043e\u043f\u0440\u043e\u0441 \u2192 \u0434\u0438\u0437\u0430\u0439\u043d\u00bb)\n\n| \u042d\u043b\u0435\u043c\u0435\u043d\u0442 \u0432\u043e\u043f\u0440\u043e\u0441\u0430 | \u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 |\n|---|---|\n| \u00ab\u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435 \u0440\u0430\u0437\u043c\u0435\u0440\u0430 (70B \u043f\u0440\u043e\u0442\u0438\u0432 13B)\u00bb | \u041e\u0441\u044c A (7B/13B/70B), \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u044b 1, 3, 4, 5 |\n| \u00ab\u043d\u0435\u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0440\u0435-training\u00bb | \u041e\u0441\u044c B (1T vs 2T), \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 2 + \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u043f\u043b\u0435\u0447\u043e (C3) |\n| \u00ab\u0441\u043b\u0430\u0431\u043e\u0435 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435\u00bb | \u041e\u0441\u044c C (base/SFT/chat), \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u044b 3, 4, 7 |\n| \u00ab\u0433\u0430\u0440\u0430\u043d\u0442\u0438\u044f \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u044f\u00bb | \u0420\u0435\u0448\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u043f. 4: \u043f\u043e\u0438\u0441\u043a \u0445\u043e\u0442\u044f \u0431\u044b \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u043b\u0438\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f, \u0433\u0434\u0435 \u0440\u0430\u0437\u043c\u0435\u0440 \u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0438 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 |\n| \u00ab\u0441\u0432\u043e\u0434\u044f\u0442\u0441\u044f \u043b\u0438 \u0432\u044b\u0433\u043e\u0434\u044b \u043d\u0430 \u043d\u0435\u0442\u00bb | \u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u044b C1 (\u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435) \u0438 C2/C3 (\u043f\u0440\u0435-training) |\n\n**\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 design-only:** \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u0438\u0437\u0430\u0439\u043d. \u041d\u0438\u043a\u0430\u043a\u0438\u0435 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u044b \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0438\u0441\u044c \u0438 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0438\u0441\u044c; \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432, \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u043e\u0432 \u0438\u043b\u0438 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b \u0432 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 \u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f; \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u044b\u0435 \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0435 \u0447\u0438\u0441\u043b\u043e\u0432\u044b\u0435 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u044f \u043e\u0442\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043a \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c. \u0414\u043b\u044f \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0434\u0438\u0437\u0430\u0439\u043d\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043b\u0438\u0441\u044c \u0431\u044b \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0441\u0435\u0442\u044f\u043c/\u043c\u043e\u0434\u0435\u043b\u044f\u043c \u0438 GPU \u2014 \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u0438\u0445 \u043d\u0435\u0442, \u0447\u0442\u043e \u043d\u0435 \u043c\u0435\u0448\u0430\u0435\u0442 \u0434\u0438\u0437\u0430\u0439\u043d-\u044d\u0442\u0430\u043f\u0443.", "assumptions": ["\u00ab\u041d\u0435\u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0440\u0435-training\u00bb = \u043f\u0440\u043e\u043a\u0441\u0438 \u00ab\u043c\u0435\u043d\u044c\u0448\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432 \u0442\u043e\u043c \u0436\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u0435\u00bb (1T vs 2T), \u0430 \u043d\u0435 \u00ab\u043c\u0435\u043d\u0435\u0435 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u0440\u043f\u0443\u0441\u00bb", "\u00ab\u0421\u043b\u0430\u0431\u043e\u0435 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435\u00bb = \u0443\u0440\u043e\u0432\u043d\u0438 base/SFT/chat (\u043f\u0440\u043e\u043f\u0443\u0441\u043a/\u0443\u0440\u0435\u0437\u0430\u043d\u0438\u0435 SFT \u0438\u043b\u0438 RLHF), \u0430 \u043d\u0435 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u043e \u0438\u0441\u043f\u043e\u0440\u0447\u0435\u043d\u043d\u044b\u0439 alignment", "1T-\u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u044b 7B/13B \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u044e\u0442\u0441\u044f/\u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0432 \u0442\u0435\u0445\u043e\u0442\u0447\u0451\u0442\u0435 Llama-2; \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0441\u043a\u0430\u0447\u0438\u0432\u0430\u0435\u043c\u043e\u0441\u0442\u044c \u043f\u043e\u0434\u043b\u0435\u0436\u0438\u0442 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438, \u043f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u2014 fallback \u043d\u0430 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0438\u043b\u0438 \u0441\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u0438\u043d\u0442\u0435\u0440\u043f\u043e\u043b\u044f\u0446\u0438\u044e", "\u0421\u043a\u0435\u0439\u043b\u0438\u043d\u0433-\u0437\u0430\u043a\u043e\u043d Chinchilla (Hoffmann et al., 2022) \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c \u043d\u0430 Llama-2 \u0434\u043b\u044f \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043f\u043e\u043a\u0440\u044b\u0442\u0438\u044f 70B@1T \u0438 \u0437\u043e\u043d\u044b \u043a\u0440\u043e\u0441\u0441\u043e\u0432\u0435\u0440\u0430; \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u043f\u043e \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u043c \u0442\u043e\u0447\u043a\u0430\u043c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430", "\u0415\u0434\u0438\u043